import json
import math
from pathlib import Path


def _reject_constant(const):
    raise ValueError("non-finite JSON constant: %s" % (const,))


def _parse_float(text):
    value = float(text)
    if not math.isfinite(value):
        raise ValueError("non-finite JSON number: %s" % (text,))
    return value


def load_payload(path):
    p = Path(path)
    try:
        text = p.read_text(encoding="utf-8")
    except OSError as exc:
        raise ValueError("cannot read payload: %s" % (exc,))
    try:
        data = json.loads(
            text, parse_constant=_reject_constant, parse_float=_parse_float
        )
    except ValueError:
        raise
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level JSON must be an object or an array")
    return data

