    return isinstance(value, int) and not isinstance(value, bool)


def _is_nonempty_str(value):
    return isinstance(value, str) and value.strip() != ""


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload.keys()) == {"name", "result"}:
        return payload["result"]
    return payload


def _validate_contact(contact):
    if not isinstance(contact, dict):
        raise ValueError("contact must be an object")
    for key in ("id", "email", "message", "chat"):
        if key not in contact:
            raise ValueError("contact missing field: %s" % (key,))
    if not _is_nonempty_str(contact["id"]):
        raise ValueError("contact id must be a non-empty string")
    for key in ("email", "message", "chat"):
        value = contact[key]
        if value is None:
            continue
        if not _is_nonempty_str(value):
            raise ValueError("contact %s must be null or a non-empty string" % (key,))


def _validate_event(event):
    if not isinstance(event, dict):
        raise ValueError("event must be an object")
    for key in ("id", "start", "end", "social", "cancelled", "attendees"):
        if key not in event:
            raise ValueError("event missing field: %s" % (key,))
    if not _is_nonempty_str(event["id"]):
        raise ValueError("event id must be a non-empty string")
    if not _is_int(event["start"]) or not _is_int(event["end"]):
        raise ValueError("event start/end must be integers")
    if not isinstance(event["social"], bool) or not isinstance(
        event["cancelled"], bool
    ):
        raise ValueError("event social/cancelled must be booleans")
    attendees = event["attendees"]
    if not isinstance(attendees, list):
        raise ValueError("event attendees must be a list")
    for attendee in attendees:
        if not _is_nonempty_str(attendee):
            raise ValueError("attendee must be a non-empty string")


def _validate_input(payload):
    if not isinstance(payload, dict):
        raise ValueError("channels input must be an object")
    for key in ("events", "day", "contacts"):
        if key not in payload:
            raise ValueError("channels input missing field: %s" % (key,))
    day = payload["day"]
    if not _is_int(day) or day < 0:
        raise ValueError("day must be an integer >= 0")
    events = payload["events"]
    contacts = payload["contacts"]
    if not isinstance(events, list):
        raise ValueError("events must be a list")
    if not isinstance(contacts, list):
        raise ValueError("contacts must be a list")
    seen_events = set()
    for event in events:
        _validate_event(event)
        if event["id"] in seen_events:
            raise ValueError("duplicate event id: %s" % (event["id"],))
        seen_events.add(event["id"])
    seen_contacts = set()
    for contact in contacts:
        _validate_contact(contact)
        if contact["id"] in seen_contacts:
            raise ValueError("duplicate contact id: %s" % (contact["id"],))
        seen_contacts.add(contact["id"])


def transform(payloads, contract):
    if not isinstance(payloads, list):
        raise ValueError("payloads must be a list")
    if not isinstance(contract, dict):
        raise ValueError("contract must be an object")
    inputs = contract.get("inputs")
    if not isinstance(inputs, list) or len(payloads) != len(inputs):
        raise ValueError("payloads must match contract inputs")
    if len(payloads) != 1:
        raise ValueError("channel_directory expects exactly one input")
    if contract.get("operation") not in (None, "channel_directory"):
        raise ValueError("unexpected operation for channels")

    payload = _unwrap(payloads[0])
    _validate_input(payload)

    directory = {}
    for contact in payload["contacts"]:
        message = contact["message"]
        chat = contact["chat"]
        if message is not None:
            primary = "message"
            address = message
        elif chat is not None:
            primary = "chat"
            address = chat
        else:
            primary = None
            address = None
        directory[contact["id"]] = {
            "email": contact["email"],
            "primary": primary,
            "address": address,
        }

    result = {"contacts": directory}
    return {"name": contract["name"], "result": result}

