    return isinstance(value, str) and value.strip() != ""


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload.keys()) == {"name", "result"}:
        return payload["result"]
    return payload


GROUP_ID = "cancelled-social"


def _validate_event_snapshot(event):
    if not isinstance(event, dict):
        raise ValueError("event snapshot must be an object")
    for key in ("id", "start", "end", "social", "cancelled", "attendees"):
        if key not in event:
            raise ValueError("event snapshot missing field: %s" % (key,))
    if not _is_nonempty_str(event["id"]):
        raise ValueError("event id must be a non-empty string")
    if not isinstance(event["attendees"], list):
        raise ValueError("event attendees must be a list")
    for attendee in event["attendees"]:
        if not _is_nonempty_str(attendee):
            raise ValueError("attendee must be a non-empty string")


def _validate_calendar_result(payload):
    if not isinstance(payload, dict):
        raise ValueError("cancel_morning result must be an object")
    for key in ("cancelled", "snapshots", "remaining"):
        if key not in payload:
            raise ValueError("cancel_morning result missing field: %s" % (key,))
    cancelled = payload["cancelled"]
    if not isinstance(cancelled, list):
        raise ValueError("cancelled must be a list")
    for item in cancelled:
        if not _is_nonempty_str(item):
            raise ValueError("cancelled ids must be non-empty strings")
    for key in ("snapshots", "remaining"):
        records = payload[key]
        if not isinstance(records, list):
            raise ValueError("%s must be a list" % (key,))
        for event in records:
            _validate_event_snapshot(event)
    snapshot_ids = [event["id"] for event in payload["snapshots"]]
    if len(set(snapshot_ids)) != len(snapshot_ids):
        raise ValueError("duplicate snapshot event id")


def _validate_channels_result(payload):
    if not isinstance(payload, dict):
        raise ValueError("channel_directory result must be an object")
    if "contacts" not in payload:
        raise ValueError("channel_directory result missing field: contacts")
    contacts = payload["contacts"]
    if not isinstance(contacts, dict):
        raise ValueError("contacts must be an object")
    for cid, entry in contacts.items():
        if not _is_nonempty_str(cid):
            raise ValueError("contact id must be a non-empty string")
        if not isinstance(entry, dict):
            raise ValueError("contact entry must be an object")
        for key in ("email", "primary", "address"):
            if key not in entry:
                raise ValueError("contact entry missing field: %s" % (key,))
        if entry["email"] is not None and not _is_nonempty_str(entry["email"]):
            raise ValueError("email must be null or a non-empty string")
        if entry["primary"] not in (None, "message", "chat"):
            raise ValueError("primary must be null, 'message' or 'chat'")
        if entry["address"] is not None and not _is_nonempty_str(entry["address"]):
            raise ValueError("address must be null or a non-empty string")
        if entry["primary"] is None and entry["address"] is not None:
            raise ValueError("address set without a primary channel")
        if entry["primary"] is not None and entry["address"] is None:
            raise ValueError("primary channel set without an address")


def transform(payloads, contract):
    if not isinstance(payloads, list):
        raise ValueError("payloads must be a list")
    if not isinstance(contract, dict):
        raise ValueError("contract must be an object")
    inputs = contract.get("inputs")
    if not isinstance(inputs, list) or len(payloads) != len(inputs):
        raise ValueError("payloads must match contract inputs")
    if len(payloads) != 2:
        raise ValueError("cancel_notifications expects exactly two inputs")
    if contract.get("operation") not in (None, "cancel_notifications"):
        raise ValueError("unexpected operation for notifications")

    calendar_result = _unwrap(payloads[0])
    channels_result = _unwrap(payloads[1])
    _validate_calendar_result(calendar_result)
    _validate_channels_result(channels_result)

    contacts = channels_result["contacts"]
    cancelled_ids = set(calendar_result["cancelled"])

    attendees = set()
    for snapshot in calendar_result["snapshots"]:
        if snapshot["id"] in cancelled_ids:
            attendees.update(snapshot["attendees"])
    unknown = attendees - set(contacts)
    if unknown:
        raise ValueError(
            "unknown contact ids in target snapshots: %s" % (sorted(unknown),)
        )

    requires = sorted(cancelled_ids)

    outbox = []
    members = []
    unreachable = []
    for cid in sorted(attendees):
        entry = contacts[cid]
        email = entry["email"]
        primary = entry["primary"]
        address = entry["address"]
        if email is not None:
            outbox.append(
                {
                    "channel": "email",
                    "to": email,
                    "recipients": [cid],
                    "requires": list(requires),
                }
            )
        if primary == "message":
            members.append(cid)
        elif primary == "chat":
            outbox.append(
                {
                    "channel": "chat",
                    "to": address,
                    "recipients": [cid],
                    "requires": list(requires),
                }
            )
        if email is None and primary is None:
            unreachable.append(cid)

    group = None
    if members:
        group = {"id": GROUP_ID, "members": members, "requires": list(requires)}
        outbox.append(
            {
                "channel": "message_group",
                "to": GROUP_ID,
                "recipients": list(members),
                "requires": list(requires),
            }
        )

    outbox.sort(key=lambda item: (item["channel"], item["to"]))

    result = {"outbox": outbox, "unreachable": unreachable, "group": group}
    return {"name": contract["name"], "result": result}

