import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

from model import load_payload
from transform import transform


def _safe_relative(root, relative):
    if not isinstance(relative, str) or relative == "":
        raise ValueError("path must be a non-empty string")
    if "\\" in relative or ":" in relative:
        raise ValueError("unsafe path: %s" % (relative,))
    if relative.startswith("/"):
        raise ValueError("absolute path is not allowed: %s" % (relative,))
    parts = relative.split("/")
    for part in parts:
        if part in ("", ".", ".."):
            raise ValueError("unsafe path segment in: %s" % (relative,))
    return Path(root) / relative


def _dump(value):
    return (
        json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            indent=2,
            allow_nan=False,
        )
        + "\n"
    )


def build_component(root, contract_path):
    root = Path(root)
    contract_path = Path(contract_path)
    contract = load_payload(contract_path)
    if not isinstance(contract, dict):
        raise ValueError("contract must be an object")
    for key in ("name", "inputs", "output"):
        if key not in contract:
            raise ValueError("contract missing field: %s" % (key,))
    if not isinstance(contract["inputs"], list):
        raise ValueError("contract inputs must be a list")

    payloads = [load_payload(_safe_relative(root, p)) for p in contract["inputs"]]
    result = transform(payloads, contract)
    if not isinstance(result, dict) or set(result) != {"name", "result"}:
        raise ValueError("transform returned an invalid envelope")

    output_path = _safe_relative(root, contract["output"])
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(_dump(result), encoding="utf-8")
    return result


if __name__ == "__main__":
    component_dir = Path(__file__).resolve().parent
    root = component_dir.parent
    build_component(root, component_dir / "contract.json")

