    path = ROOT / "outputs" / "core_manifest.json"
    try:
        core = json.loads(path.read_text(encoding="utf-8"))
    except OSError as exc:
        raise ValueError("cannot read core manifest: %s" % (exc,))
    if not isinstance(core, dict) or set(core) != {"components"}:
        raise ValueError("core manifest must contain exactly 'components'")
    if not isinstance(core["components"], dict):
        raise ValueError("core components must be an object")
    return core


def _non_empty(value):
    if isinstance(value, (list, dict, str, tuple, set)):
        return len(value) > 0
    return False


def _attention(components):
    flagged = set()
    for name, result in components.items():
        if not isinstance(result, dict):
            continue
        if result.get("blocked") is True:
            flagged.add(name)
        for key in ("complete", "checkout", "committed", "ok"):
            if result.get(key) is False:
                flagged.add(name)
        for key in ("unavailable", "missing", "conflicts", "unreachable"):
            if key in result and _non_empty(result[key]):
                flagged.add(name)
    return sorted(flagged)


